const k=[{id:"optimism-maier-seligman",title:"O01 · Maier ve Seligman · 2016 · Öğrenilmiş çaresizliğe elli yıl sonra bakış",url:"https://doi.org/10.1037/rev0000033",type:"research",finding:"Derleme, öğrenilmiş çaresizlik açıklamasını yeniler: hayvanların olumsuz uyaranlara maruz bırakıldığı deneylerde uzun süren uyarım pasiflik doğurur. Kontrolü fark etmek koruyucu sinir devrelerini harekete geçirir.",limitation:"Çoğunlukla hayvan deneyleri. İnsan tedavilerini birleştiren bir derleme değil. Donup kalmanın her insanda varsayılan tepki olduğunu veya kontrol listesi alıştırmasının etkisini göstermez."},{id:"optimism-malouff-schutte",title:"O03 · Malouff ve Schutte · 2017 · Çalışmalar iyimserliği artırabilir mi?",url:"https://doi.org/10.1080/17439760.2016.1221122",type:"research",finding:"3.319 kişiyi kapsayan 29 randomize araştırmada psikolojik çalışmalar iyimserlik puanlarını ortalama olarak artırdı: g = 0,41.",limitation:"Yöntem ve takip süreleri farklıydı. Kısa takip ve takibi tamamlayanlarla yapılan analizler daha büyük etkiler verdi. Açılan kayıtta güven aralığı doğrulanmadı. Kalıcı değişimi veya ODA’nın etkisini göstermez."},{id:"optimism-sweeney",title:"O02 · Sweeney, Anderson ve Bailey · 1986 · Açıklamalar ve depresyon",url:"https://doi.org/10.1037/0022-3514.50.5.974",type:"research",finding:"Yaklaşık 15.000 kişiyi kapsayan 104 araştırmada depresyon, olumsuz olayları kişinin kendisine bağlayan, kalıcı ve yaygın açıklamalarla ilişkiliydi.",limitation:"İlişki neden-sonucu göstermez veya olumsuz açıklamayı yanlış kılmaz. Açılan özette birleştirilmiş etki ve güven aralıkları doğrulanmadı. Rahatlatıcı bir açıklama her zaman doğru değildir."},{id:"optimism-hofmann",title:"O06 · Hofmann ve arkadaşları · 2012 · BDT meta-analizlerinin derlemesi",url:"https://doi.org/10.1007/s10608-012-9476-1",type:"research",finding:"Derleme 269 bilişsel davranışçı terapi meta-analizi belirledi, temsili 106’sını inceledi. Kanıt tedavi programlarının bütünüyle ilgiliydi ve soruna göre değişiyordu.",limitation:"Bu sayılar, düşünce kayıtlarının tek başına sınandığı deney sayıları değildir. ODA formunu doğrulamaz. Ayrı düzeltme notunun metnine doğrulama için ulaşılamadı."},{id:"optimism-brunwasser",title:"O05 · Brunwasser, Gillham ve Kim · 2009 · Penn Resiliency Programı derlemesi",url:"https://doi.org/10.1037/a0017671",type:"research",finding:"2.498 genci kapsayan 17 kontrollü araştırmada çok oturumlu program, hiçbir uygulama yapılmamasına göre depresyon belirtilerinde küçük faydalar gösterdi.",limitation:"Başka etkin uygulamalara üstünlük ve depresyon tanılarını önleme gösterilmedi. Gençlere yönelik bu program, yetişkinin tek bir ABCDE çalışmasını doğrulamaz."},{id:"optimism-ellis-abc",title:"O12 · Albert Ellis Institute · Uzmanlar için ABC açıklaması",url:"https://albertellis.org/wp-content/uploads/2021/09/Emotional-Disturbance-and-Its-Treatment-in-a-Nutshell-ABCs-.pdf",type:"guidance",finding:"Uzmanlara yönelik açıklama olayı, inançları, sonuçları, katı inançları sorgulamayı ve daha işlevsel bir bakış geliştirmeyi anlatır.",limitation:"Bir yöntem belgesi, etki deneyi değil. Ellis’in son adımı, sonraki “enerji kazanma” sürümleriyle aynı sayılmamalı. ODA’nın kısa çalışması bir uyarlama."},{id:"optimism-beck-thought-record",title:"O13 · Beck Institute · Düşünce kaydı formu",url:"https://beckinstitute.org/wp-content/uploads/2021/08/Thought-Record-Worksheet.pdf",type:"guidance",finding:"Klinik form durumu, düşünceyi, duyguyu, kanıtı, dengeli yanıtı ve sonraki puanları kaydeder.",limitation:"Klinik bir yöntem, tek başına etki deneyi değil. ODA’nın kısa uyarlaması BDT tedavisi değildir. Dengeli yanıt sıkıntıyı azaltmak zorunda değil."},{id:"optimism-reivich-mrt",title:"O14 · Reivich, Seligman ve McBride · 2011 · Psikolojik dayanıklılık eğitimi",url:"https://doi.org/10.1037/a0021897",type:"guidance",finding:"Program açıklaması ABC’yi, düşünce hatalarına bakmayı, en kötü, en iyi ve en olası ihtimalleri düşünüp plan yapmayı içerir.",limitation:"On günlük eğitici kursunun açıklaması. Bu alıştırmaların tek başına veya ODA kursunun bütün olarak etkisini göstermez."},{id:"optimism-landau-inquiry",title:"O11 · Landau ve arkadaşları · 2021 · Rehberli sorgulama araştırması",url:"https://doi.org/10.1001/jamanetworkopen.2021.39670",type:"research",finding:"BRCA varyantları olan 100 kadınla kaydı yapılmış randomize araştırma, 12 haftalık rehberli sorgulamayı olağan sağlık bakımıyla karşılaştırdı. Bazı iyi oluş sonuçlarında fayda bildirdi.",limitation:"Haftalık üç saatlik gruplar ve rehber desteğiyle çalışma, kısa bir kişisel ders değildir. Olağan sağlık bakımında eşit ilgi yoktu. BDT eşdeğerliğini veya istismar ve travmaya uygunluğu göstermez."},{id:"optimism-katie-instructions",title:"O15 · Byron Katie International · The Work yönergeleri",url:"https://thework.com/instruction-the-work-byron-katie/",type:"technique",finding:"Uygulama yönergeleri dört sorgulama sorusunu, ardından düşünceyi başka yönden ele almayı ve gerçek örnekler bulmayı anlatır.",limitation:"Yönergeler bilimsel kanıt değildir. Farklı yorum isteğe bağlı kalsın. Örnek uydurma veya kendini suçlamaya zorlama. Uzun programı sınayan araştırma rehber desteği kullandı."},{id:"optimism-nhs-cbt",title:"O16 · NHS · Bilişsel davranışçı terapi",url:"https://www.nhs.uk/tests-and-treatments/cognitive-behavioural-therapy-cbt/",type:"guidance",finding:"NHS rehberi düzenli BDT tedavisini ve profesyonel yardıma ulaşma yollarını anlatır.",limitation:"Rehber ODA’yı tedavi olarak onaylamaz veya sonuç garantilemez. Pratik korunma ve profesyonel bakım, kendi başına düşünme alıştırmasından önce gelir."},{id:"optimism-three-good-things",title:"O07 · Seligman ve arkadaşları · 2005 · Pozitif psikoloji çalışmaları",url:"https://doi.org/10.1037/0003-066X.60.5.410",type:"research",finding:"İlk çevrim içi deney bir haftalık alıştırmalar kullandı. “Üç iyi şey”, bir hafta boyunca her gece üç olayı ve nedenlerini yazmaktı.",limitation:"Başlangıçtaki 577 kişiden 411’i takibi tamamladı. Çoğu beyaz, eğitimli gönüllülerdi. Devam etmek rastgele belirlenmedi. Kalıcı fayda garantisini veya klinik tedaviyi kanıtlamaz."},{id:"optimism-mongrain",title:"O08 · Mongrain ve Anselmo-Matthews · 2012 · Olumlu alıştırmaların tekrarı",url:"https://doi.org/10.1002/jclp.21839",type:"research",finding:"Tekrar araştırmasında adı geçen alıştırmalarla da olumlu plaseboyla da mutluluk artışı görüldü. Depresyon için özgül bir fayda gösterilmedi.",limitation:"Açılan özette katılımcı sayısı ve sayısal etkiler doğrulanmadı. Bulgular, alıştırmaya özgü etkiyi daha az destekler. Bütün olumlu alıştırmaların işe yaramadığını kanıtlamaz."},{id:"optimism-nimh-support",title:"O20 · NIMH · Depresyon rehberi",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Süren belirtiler veya günlük işleri yapmakta güçlük, uzman değerlendirmesi gerektirir. Kriz desteği alınabilir.",limitation:"Bu bir rehber, uygulamayla konulan tanı değil. Yardım istemek için iki hafta beklemek veya kursu bitirmek gerekmez."}],d=[{schemaVersion:2,revision:2,id:"optimism-1",courseId:"optimism",locale:"tr",title:"Reddedildin mi? Elindeki bir imkânı dene",goal:"Önemsediğin, riski düşük bir aksilik seç. Etki edebileceğin konuda işe yarayan tek bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bir ret cevabı yüzünden her yol kapandı mı? Sonraki kararından önce elindeki bir imkânı dene.",reason:{id:"optimism-1-reason-available-step",label:"Yapabileceğin hangi adımı baştan eledin? Bu kararını hangi bilgi destekliyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Elediğim bir seçeneğe yeniden bakmak","Yerinde bir bırakma kararını korumak","Yapabileceğim bir düzeltmeyi denemek"]},why:{id:"optimism-1-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir aksilik yaşamanla bundan sonra yapabileceğin şey aynı değil. Başkasına işini onaylatamazsın. Ama hangi koşulu karşılamadığını sorabilir, bir beceriyi deneyebilir veya yardım isteyebilirsin. Bütün durumu kontrol edebildiğini söylemek yerine, deneyebileceğin tek bir kısmı seç. Sonuç hakkındaki belirsizliği de olduğu gibi bırak.","Araştırmalarda psikolojik uygulamalar iyimserlik puanlarını ortalama olarak değiştirdi. Bu puanlar beklentileri ölçer. Ret cevabının değişeceğini kanıtlamaz. Bu kursta gündelik bir aksiliği ve ardından attığın adımı takip edeceğiz. Adımını kaydet, dene, gelen yanıtı veya yanıt gelmediğini yaz. Takvime eklemek hazırlık; soruyu göndermek ise işi yapmaktır."],example:{title:"Ece soruyor, yanıt henüz gelmiyor",text:"Ece’nin taslağı reddedilince önemsediği projeyi bırakmak aklına geliyor. Saat 12.30’da güvenle konuşabildiği ekip grubuna soruyor: “Önce hangi eksiği gidermeliyim?” O öğleden sonra yanıt gelmiyor. Kaydına soruyu gönderdiğini yazıyor. Geri bildirim istemeyi denedi. Projenin kabul edileceğini kanıtlamış olmadı. Yanıt gelmemesi, soruyu sormadığı anlamına da gelmiyor. Sonraki kararında bu ayrımı koruyor."}},move:{invitation:"Gündelik bir aksilik seç. Elindeki bir imkânı dene, sonra gerçekte ne olduğunu kaydet.",instructions:["Kurs boyunca aynı aksilik ve seçtiğin amaç üzerinde çalış.","Yalnızca takvime ekleme; gerçekten yapacağın bir iş seç."],prompts:[],suggestions:{action:["Belirli bir eksik hakkında tek soru gönder","Bildiğim eksiklerden birini gider","Bu aksilik için pratik yardım iste"],minimum:["Geri bildirim isteyen tek açık cümle gönder","Bildiğim tek bir hatayı düzelt","Pratik yardım için tek bir istekte bulun"],cue:["Sıradaki güvenli ekip görüşmemiz başladığında","Reddedilen taslağı yeniden açıp başına geçtiğimde","İhtiyacım olan desteğe ulaşabildiğim ilk fırsatta"],place:["Güvenle konuşabildiğim mesaj grubumuzda","Her zamanki çalışma yerimde"],fallback:["Birinden eksik koşullardan birini açıkça belirtmesini iste","Bildiğim bir eksiği gidermeye başla","Yanıt alamadığım iletişim yolu yerine başkasını seç"],observation:["Soruyu gerçekten gönderip göndermediğim","Gelen yanıt veya yanıt gelmemesi","Hangi kısma etki edebildiğim"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Belirli bir eksik hakkında tek soru gönder",minimum:"Geri bildirim isteyen tek açık cümle gönder",minutes:2,cueHint:"Sıradaki güvenli ekip görüşmemiz başladığında",placeHint:"Güvenle konuşabildiğim mesaj grubumuzda",obstacleHint:"Etki edebileceğim bir koşulu henüz belirleyemiyorum.",fallbackHint:"Birinden eksik koşullardan birini açıkça belirtmesini iste",observationHint:"Soruyu gerçekten gönderip göndermediğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-1-review-window-decision",scenario:"Ece’nin taslağı neden belirtilmeden reddedilmiş. Raporu inceleyen kişiye soru sormak için on dakikası kalmış. Düzeltme iki saat alacak. Bu zamanı ayırmaya değip değmeyeceğini öğrenmek istiyor.",question:"Şimdi hangi adım bu kararı daha sağlam bilgiyle vermesini sağlar?",options:[{id:"optimism-1-inspect-brief",text:"Eski yönergeyi on dakika inceleyip ret sebebi olduğunu düşündüğü koşulu ardından düzeltmeye başlamak.",feedback:"Yönergeye bakmak gerçekten eksik bir şeyi gösterebilir. Ama ret nedenini hâlâ öğrenmiş olmaz ve soru sorabileceği son dakikaları kullanır. Önce şimdi sor; ardından ilgili koşula dönüp bak."},{id:"optimism-1-ask-criterion",text:"Hangi koşulun eksik kaldığını sorup gelen yanıta göre yapabileceği tek bir düzeltme seçmek.",feedback:"Bu seçim, bilgi alabileceği fırsatı kapanmadan kullanır. Yanıt, düzeltmeyi, yardım istemeyi veya bırakmayı haklı kılabilir. Ece’nin yaptığı iş soruyu göndermektir. Yanıt alması, bu adımı tamamlamasının şartı değildir."},{id:"optimism-1-send-partial-rewrite",text:"Soru sorma süresi dolmadan çabasını göstermek için taslağın on dakikada düzeltebildiği kısmını göndermek.",feedback:"Kısmi düzeltme asıl eksiği giderirse işe yarayabilir. Ama ret nedeni bilinmiyor. Ece tahminle ilerlemiş olur. Düzeltmeye zaman ayırmadan önce bu fırsatta hangi değişikliğin gerektiğini sorsun."}],bestOptionId:"optimism-1-ask-criterion"}},carry:{takeaway:"Aksilikten sonra etki edebileceğin tek bir adımı dene. Bu adımın gerçekte neyi değiştirdiğini kaydet.",followUp:{questionId:"optimism-1-return",question:"Yapabileceğin adımı attın mı? Yeni bilgi mi geldi, yanıt mı gelmedi, yoksa yeni bir engel mi çıktı?",observationPrompt:"Adımdan sonra hangi bilgi veya yeni engel çıktı? Yanıt gelmediyse onu da yaz.",adjustmentPrompt:"Öğrendiklerine göre şimdi hangi adım sana daha uygun?"}},goDeeper:{sections:[{heading:"Hayvan araştırmalarındaki açıklama sonradan değişti",paragraphs:["Maier ve Seligman’ın 2016 derlemesi, onlarca yıllık hayvan araştırmasına bakarak öğrenilmiş çaresizliğin açıklamasını yeniden ele alır. [O01] İncelenen deneylerde uzun süre olumsuz uyarana maruz kalmak pasifliği doğurur. Kontrolü fark etmek ise koruyucu sinir devrelerini harekete geçirir. Bu açıklama, uzun süre olumsuz olaylara maruz bırakılan sıçan ve köpeklerle ilgilidir. Bir yetişkinin gündelik hayatta reddedilen taslağına ilişkin doğrudan bir deney değildir.","Derleme, donup kalmanın her insanda varsayılan tepki olduğunu, her çaresizliğin aynı mekanizmadan kaynaklandığını veya kontrol edilebilir işleri listelemenin klinik bir sorunu giderdiğini göstermez. Bu yüzden ders, tepkine bir beyin açıklaması yapıştırarak başlamıyor. Önce pratik bir ayrım yapıyoruz: raporu inceleyen kişinin kararı başka bir olay, senin gönderebileceğin soru başka bir olay. İkisini aynı sonuca bağlamak zorunda değilsin.","ODA’nın aksilikten sonra tek adım denemesi bir uyarlama. Elindeki imkânın pek bir şeyi değiştirmediğini de görebilirsin. Koşullar yardım almayı veya başka bir yön seçmeyi gerektirebilir. Bu sonucu da sakla. Bir şeyi gerçekten denemek, umudunun geri geleceğine söz vermeden sana bilgi sağlar. Bu bilgiyle aynı adımı sürdürmek, değiştirmek veya bırakmak arasında daha somut bir karar verebilirsin."]},{heading:"Beklentinin değişmesi, sonucun garantisi değil",paragraphs:["Malouff ve Schutte, 3.319 kişinin katıldığı 29 randomize araştırmayı birleştirdi. [O03] Psikolojik çalışmalar iyimserlik puanlarını ortalama olarak artırdı: g = 0,41. Yöntem, sunuluş biçimi ve takip süresi değişiyordu. Daha kısa takipte ve yalnızca takibi tamamlayanlara bakan analizlerde daha büyük etkiler bulundu. Bu ortalama araştırma gruplarını anlatır. Tek denemeden sonra senin beklentinin ne kadar değişeceğini söylemez.","Derleme, kişiliğin kalıcı değiştiğini, nesnel sonuçların iyileştiğini veya bu ODA kursunun etkisini göstermiyor. Geri bildirim isteyerek hangi koşulun arandığını öğrenmeyi denersin. Sonradan kabul edileceğine söz veremez. Yine de gelen yanıt, düzeltmenin ayıracağın zamana değip değmediğini, yardım gerektirip gerektirmediğini veya artık sana uymadığını anlamana yardım edebilir. Henüz yanıt yoksa sonucu biliyormuş gibi yazmak yerine belirsizliği kayıtta koru.","Bir sonraki adımın başka bir iş yerine destek istemek olabilir. NIMH rehberi, süren belirtilerde veya günlük işleri yapmak zorlaştığında uzman değerlendirmesini önerir. [O20] Dersleri bitirmeden yardım isteyebilirsin. Belirli bir süre dolmasını da beklemek gerekmez. Birinden gerçekten yardım istemek, kendi başına anlamlı bir adım olabilir. Yardım istemeyi planlamanla isteği göndermen ayrı olaylar olarak kalsın."]}],sourceIds:["optimism-maier-seligman","optimism-malouff-schutte","optimism-nimh-support"]}},{schemaVersion:2,revision:2,id:"optimism-2",courseId:"optimism",locale:"tr",title:"Tek taslak yüzünden kendini silip attın mı?",goal:"Aksiliğin doğru nedenini koru. Kendin hakkında toptan hüküm vermeden işe yarayan tek bir düzeltme dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Reddedilen taslak “Ben bu işi yapamam”a mı dönüştü? Olanı doğru anlat, sonra tek bir düzeltme dene.",reason:{id:"optimism-2-reason",label:"Hangi kısmı sen değiştirebilirsin? Hangi kısmı henüz bilmiyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Düzeltebileceğim kısmın sorumluluğunu almak","Henüz bilmediğim kısmı belirtmek","İşe yarayan tek düzeltmeye dönmek"]},why:{id:"optimism-2-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe ve kaydettiğin yanıta geri dön. Aksilikleri kalıcı, hayatın birçok alanını etkileyen ve kişinin kendisinden kaynaklanan olaylar olarak açıklamak depresyonla ilişkili. Bu ilişki, birinin diğerine neden olduğunu kanıtlamaz. Canını acıtan her açıklamanın yanlış olduğu anlamına da gelmez. Elindeki bilgiye bakarak hangi kısmın doğru kaldığını ayır.","Sor: Bu durumun nedeni ne kadar sürebilir? Hayatın hangi kısmını etkiliyor? Hangi kısım bana ait, hangisi bilinmiyor? Uzun süren bir beceri eksiği gerçek olabilir. Bunu söyle, ama tek taslaktan her şey hakkında hüküm çıkarma. Bir düzeltme dene. Rahatlatıcı bir neden uydurmak yerine sorumluluğunu ve belirsizliği koru."],example:{title:"Ece belirli bir eksiği düzeltiyor",text:"Ece, reddedilen taslağın müşterinin bütçe sorusuna yanıt vermediğini öğreniyor. Saat 7.00’de “Ben bu işte iyi değilim” yerine eksiği açıkça anlatıyor: bütçe bölümü tamamlanmamıştı. İşe yarayan tek bir açıklama ekleyip değerlendirmeye gönderiyor. Raporu inceleyen kişi hâlâ daha çok ayrıntı istiyor. Ece bir düzeltme yaptı. Projenin bütünü hakkındaki sonuç ise henüz belli değil."}},move:{invitation:"Aynı aksiliği kullan. Doğru bir neden belirle, sonra onun gerektirdiği düzeltmeyi yap.",instructions:["Bilgi destekliyorsa kalıcı koşulları ve kendi payını açıkça koru.","İşe yarayan tek düzeltmeyi yap. Gerçekte çıkan sonucu kaydet."],prompts:[],suggestions:{action:["Bildiğim eksiklerden birini gider","Yönergenin hangi kısmının eksik kaldığını sor","Belirlediğim beceriyi bir kez dene"],minimum:["Taslakta tamamlanmamış tek satırı düzelt","Eksik bilgiyi açıklığa kavuşturan tek soru gönder","Beceriyi bir kez dene"],cue:["Aynı taslağı yeniden açıp başına geçtiğimde","Sıradaki güvenli geri bildirim fırsatımız geldiğinde","İstenen koşulu okuduktan sonra"],place:["Düzelttiğim taslağın ilgili bölümünde","Güvenle geri bildirim alabildiğim iletişim kanalında"],fallback:["Koşulu yeniden oku, bilgilerin gösterdiği eksiği düzelt","Gerekli bilgi eksikse bunu açıkça sor","Beceri eksiğim için birinden yardım iste"],observation:["Gerçekte hangi kısmı düzelttiğim","Hangi nedenin hâlâ bilinmediği","Geri bildirimin açıklamama uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bildiğim eksiklerden birini gider",minimum:"Taslakta tamamlanmamış tek satırı düzelt",minutes:2,cueHint:"Aynı taslağı yeniden açıp başına geçtiğimde",placeHint:"Düzelttiğim taslağın ilgili bölümünde",obstacleHint:"Tek başarısızlıktan bütün işlerim hakkında hüküm çıkarıyorum.",fallbackHint:"Koşulu yeniden oku, bilgilerin gösterdiği eksiği düzelt",observationHint:"Gerçekte hangi kısmı düzelttiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-2-budget-gap-decision",scenario:"Ece’nin raporunu inceleyen kişi bütçede eksik tek bir varsayımı belirtmiş. Diğer bölümler yönergeye uyuyor. Düzeltme için on dakika kalmış. Ece bu eksiğin işi yapamadığını kanıtladığını düşünüyor.",question:"Hangi yanıt bilgiye ve kalan süreye daha uygun?",options:[{id:"optimism-2-rewrite-budget",text:"Raporu inceleyen kişinin bütünüyle yeni bir sürümü inceleyebilmesi için şimdi bütçe bölümünün tamamını yeniden yazmak.",feedback:"Bir bölümde birbiriyle bağlantılı birçok sorun varsa yeniden yazmak işe yarayabilir. Burada tek bir varsayım eksik ve süre kısa. Kabul edilmiş kısımları değiştirmeden bu belirli eksiği tamamla."},{id:"optimism-2-clarify-first",text:"Bölümü değiştirmeden önce raporu inceleyen kişiden eksik varsayımı yeniden anlatmasını isteyip gelecek açıklamayı beklemek.",feedback:"Geri bildirim belirsizse açıklama istemek işe yarar. Burada gereken koşul zaten belirtilmiş. Beklemek süreyi kaçırabilir. Bilinen eksiği düzelt, sonra bu düzeltmenin koşulu karşılayıp karşılamadığını sor."},{id:"optimism-2-specific-correction",text:"Bütçedeki eksiği kabul edip tek bir kısmı düzeltmek, işi yapamadığına ilişkin geniş hükmü kesinleştirmemek.",feedback:"Bu seçim bilgilerin desteklediği eksiği kabul eder ve kısa süreyi onu gidermek için kullanır. Düzeltmenin koşulu karşılayıp karşılamadığını sor. Yeni geri bildirim de bu taslak hakkında bilgi sağlar. Mesleğin hakkında kesin hüküm vermez."}],bestOptionId:"optimism-2-specific-correction"}},carry:{takeaway:"Doğru bir açıklama canını sıkabilir. Yine de işe yarayan bir düzeltmenin yolunu gösterebilir.",followUp:{questionId:"optimism-2-return",question:"Düzeltmen, bilgilerin desteklediği bir nedeni ele aldı mı? Açıklamanın hangi kısmı hâlâ bilinmiyor?",observationPrompt:"Hangi nedeni ele aldın? Hangi kısmı hâlâ bilmiyorsun, henüz ne öğrenmedin?",adjustmentPrompt:"Şimdi hangi eksik için düzeltme, açıklama veya birinden yardım gerekiyor?"}},goDeeper:{sections:[{heading:"Rahatlatıcı cevap aramak yerine soruyu açık tut",paragraphs:["Sweeney ve arkadaşları, yaklaşık 15.000 kişinin yer aldığı 104 araştırmayı inceledi. [O02] Farklı örneklem ve görevlerde, olumsuz olayları kişinin kendisine bağlayan, kalıcı ve yaygın açıklamalar depresyonla ilişkiliydi. Bu boyutlar kişinin payını, süren nedenleri ve geniş etkileri ele alır. Her aksiliğin yalnızca tek bir nedeni olması gerektiğini söylemez. Bulunan ilişki de hangi etkenin diğerine neden olduğunu göstermez.","Bu derste bu boyutlarla açıklamana bakıyoruz. Sana neşeli bir sonuç dayatmıyoruz. Uzun süren bir koşul uzun sürebilir. Senin atladığın bir gereklilik yine senin düzeltmen gereken kısım olabilir. Ortak nedenler de bulunabilir; bazılarıysa hâlâ bilinmeyebilir. Her açıklamayı “Geçici ve benim dışımda” diye değiştirmek doğruluğu kaybettirir. Rahatlamasan da eldeki bilgiye uyan bir açıklamayı koruyabilirsin.","Bu soruyu, kurs boyunca denediğin aynı adım için sor. Hangi kısmı düzeltebilir, kontrol edebilir veya yardım alarak ele alabilirsin? Belirli bir işi denemek, yeteneğin hakkındaki geniş bir iddiayı sınamaktan daha kolaydır. Yaptığın işi kaydet. Bu işin sonucuna getirdiğin yorumu ayrı tut. Bir düzeltmenin yapılması, hem o düzeltme hem bütün kariyerin hakkında aynı ölçüde bilgi sağlamaz."]},{heading:"Adil bir açıklamada gerçek sorun da kalabilir",paragraphs:["Beck Institute’un düşünce kaydı yöntemi kanıtları, başka açıklamaları, dengeli bir yanıtı ve sonraki gözlemleri içerir. [O13] Bu klinik form, buradaki kısa açıklama çalışmasının tek başına ruh hâlini iyileştirdiğinin kanıtı değildir. ODA’nın kısa uyarlamasının bağımsız bir tedavi etkisi gösterilmiş değil. Onu rahatlatıcı bir açıklama üretme zorunluluğu olarak değil, bilgilere uyan bir düzeltme bulmak için kullan.","Dengeli bir açıklama hoşuna gitmeyen gerçekleri de içerebilir. Bütçe bölümü eksik, süre dar veya beceri çalışmak gerekiyor olabilir. Bilinmeyen kısımlar da açık kalabilir. Sonraki işin başka bir rahatlatıcı cümle kurmak olmayabilir. Bir düzeltme yapman, tarafsız bir soru sorman veya yardım istemen gerekebilir. Yanıtın daha iyi hissettirmesi ile önündeki soruna uygun olması aynı şey değil.","NHS rehberi, bilişsel davranışçı terapiyi düzenli bir tedavi olarak anlatır ve profesyonel yardıma ulaşma yollarını gösterir. [O16] Bu kurs eğitim sunar. Kendi başına aynı düşünceyi tekrar tekrar irdelemek sıkıntını artırıyorsa veya günlük işlerini aksatıyorsa çalışmayı durdur ve uygun destek iste. Güvenliğin ve pratik ihtiyaçların, iyimser görünmekten önce gelir. Kendini korumak da yerinde bir sonraki adım olabilir."]}],sourceIds:["optimism-sweeney","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-3",courseId:"optimism",locale:"tr",title:"Öfkeli mesaj hazır mı? Önce olanı ayır",goal:"Aynı aksiliğe kısaca bak. Ardından arkasında durabileceğin, işe yarayan tek bir yanıtı ver veya düzeltmeyi yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kendini savunmak için yazdığın mesajı göndermek üzeresin. Olanı doğru anlat, ardından yarın da arkasında duracağın bir yanıt seç.",reason:{id:"optimism-3-reason",label:"Hangi yanıt hem bugün hem yarın istediğin hayata katkı sağlar?",kind:"text",maxLength:160,optional:!0,suggestions:["Belirli bir hatamı kabul etmek","Mesleğime hüküm vermeden yanıtlamak","Önümdeki pratik sorunu çözmek"]},why:{id:"optimism-3-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Teslim tarihini kaçırmak olmuş bir olay. “Ben bu işi yapamam” ise daha geniş bir inanç. Kaynaklarda anlatılan bir yöntem, olayı, inancı ve ardından gelen duygu veya davranışı ayırır. Düşünceler yanıtını etkileyebilir. Ama her duyguyu tek başına açıklamaz. Hangi kısmın olay, hangi kısmın yorum olduğunu bilerek başla.","Aynı aksiliğe dön. Tek bir olayı tarafsızca anlat, inancını eldeki bilgilerle karşılaştır ve işe yarayan bir yanıt seç. Kaygın doğruysa o kısmı koru, çözüm ara. Adil bir yanıtla sorumluluk alabilir, bir istekte bulunabilir veya sınır koyabilirsin. Utancın veya öfkenin geçmesini beklemeden bu adımı atabilirsin."],example:{title:"Ece sorumluluk alarak yanıtlıyor",text:"Ece düzeltilmiş raporun teslim tarihini kaçırıyor. Saat 6.30’da kendini savunmak için mesaj yazmaya başlıyor. Sonra olayı “Ben bu işi yapamam” hükmünden ayırıyor. “Bugünkü teslimi kaçırdım. Düzeltilmiş bölümü yarın öğlene kadar gönderebilirim. Uyar mı?” diye yazıp gönderiyor. Yöneticisi saati kabul ediyor ama hâlâ kızgın. Ece hem anlaşmayı hem bitmemiş işini kaydediyor."}},move:{invitation:"Aynı aksilikte inancına kısaca bak. Ardından duruma uygun, adil tek bir yanıtı ver.",instructions:["Gözleyebildiğin tek olayı kendin hakkındaki geniş hükümden ayır.","İşe yarayan bir düzeltme, istek veya sınır cümlesi gönder."],prompts:[],suggestions:{action:["Sorumluluk alıp düzeltme öneren tek yanıt gönder","Yapabileceğim bir teslim tarihi için istekte bulun","Anlaştığımız düzeltmelerden işe yarayan birini tamamla"],minimum:["İşe yarayan tek bir yanıt cümlesi gönder","Yapabileceğim tek bir sonraki adımı açıkça söyle","Anlaştığımız işin tek yararlı parçasını bitir"],cue:["Zor mesajı göndermeden hemen önce","Sıradaki güvenli düzeltme görüşmemiz başladığında","Anlaştığımız işe yeniden başladığımda"],place:["Güvenle konuşabildiğim iş mesajı grubumuzda","Her zamanki çalışma yerimde"],fallback:["Olayı ve yapılabilir adımı yaz, sonra gönder","Birinden olayları anlattığım yanıta bakmasını iste","Bunun yerine pratik yardım almayı seç"],observation:["Gerçekte ne gönderdiğim veya değiştirdiğim","Anlaştığımız konu veya anlaşmaya varılamaması","Kaygımın hangi kısmının doğru kaldığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Sorumluluk alıp düzeltme öneren tek yanıt gönder",minimum:"İşe yarayan tek bir yanıt cümlesi gönder",minutes:2,cueHint:"Zor mesajı göndermeden hemen önce",placeHint:"Güvenle konuşabildiğim iş mesajı grubumuzda",obstacleHint:"Asıl hatayı ele almadan önce kendimi savunmak istiyorum.",fallbackHint:"Olayı ve yapılabilir adımı yaz, sonra gönder",observationHint:"Gerçekte ne gönderdiğim veya değiştirdiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-3-decision",scenario:"Ece’nin yöneticisi teslim tarihini kaçırdığını söylüyor. Bu doğru. Ece “Ben bu işi yapamam” diye düşünüyor ve kendini savunmak istiyor.",question:"İnancına adilce bakmayı hangi adımla daha iyi uygular?",options:[{id:"optimism-3-own-and-correct",text:"Kaçırdığı tarihi kabul edip mesleği hakkındaki hükmü açık bırakmak ve yapabileceği bir düzeltmede anlaşmak.",feedback:"Bu seçim gerçek olayı korur ve geniş hükmü sınar. Utanç sürse de yapabileceği bir düzeltme önerir. Yöneticinin onayı, gözlenecek bir sonuçtur. Ece’nin kendi adımını tamamlaması için şart değildir."},{id:"optimism-3-past-reviews",text:"Eleştiri daha az tehdit edici gelene kadar eski olumlu yorumları okuyup ardından yanıt verip vermeyeceğine karar vermek.",feedback:"Eski geri bildirim, toptan hükmünü sorgulatabilir. Ama bugünkü kaçırılmış tarihi ele almaz. Rahatlamayı beklemek pratik yanıtı geciktirir. İlgili bilgilere kısaca bak, sonra yapabileceğin tek bir düzeltmeyi öner."},{id:"optimism-3-pressure-first",text:"Düzeltmeyi konuşmadan önce yaşadığı baskıyı açıklayıp yöneticisinden gösterdiği çabanın farkına varmasını istemek.",feedback:"İş yükü baskısı gerçek olabilir. Sınır koymak veya destek almak gerekebilir. Ama çabanın görülmesini şart koşmak düzeltmeyi erteler. Belirli teslim eksiğini kabul ederken yapabileceğin bir değişiklik de iste."}],bestOptionId:"optimism-3-own-and-correct"}},carry:{takeaway:"Gerçek olayı koru. Geniş hükmü sınayıp işe yarayan sonuca göre bir adım at.",followUp:{questionId:"optimism-3-return",question:"Verdiğin yanıt, zor duygu sürse de gerçek sorunu ele aldı mı?",observationPrompt:"Yanıtın, gerçekte yaşanan hangi sorunu ele aldı veya hangi kısmı çözümsüz bıraktı?",adjustmentPrompt:"Hangi kısım hâlâ düzeltme, bir istek veya güvenli bir sınır gerektiriyor?"}},goDeeper:{sections:[{heading:"ABCDE yöntemi nereden geliyor?",paragraphs:["Albert Ellis Institute’un uzmanlara yönelik açıklaması olayı, inançları ve sonuçları ayırır. Ardından katı inançların sorgulanmasını ve daha işlevsel bir bakış geliştirmeyi anlatır. [O12] Daha sonraki psikolojik dayanıklılık eğitimlerinde son adım için “enerji kazanma” ifadesi kullanılır. [O14] Bu adlar aynı şeyi anlatan, kesin duygu değişimi vaatleri değildir. Ellis’in son adımını sonraki bütün sürümlerle aynı saymak kaynaklar arasındaki farkı siler.","Bu kaynaklar yöntemleri anlatır. Yetişkinin kısa bir ABCDE çalışmasından tek başına fayda göreceğini göstermez. ODA daha kısa bir sıra kullanır: olayı anlat, inancına bak ve durumun gerektirdiği ölçüde yanıt ver. Duygular koşullardan, kayıptan, sağlıktan ve destekten de etkilenir. İnançları sıralamak, duygunun tam açıklaması değildir. Hangi kısmın gerçekten değiştirilebileceğini anlamaya yardım eden bir araç olarak kalabilir.","Sürdürdüğün denemede bu yöntemi yalnızca gözlediğin bir sorunu çözmeye yardım ediyorsa kullan. Her adım atışında beş harfi doldurman gerekmiyor. Kaygın haklıysa yararlı yanıt, onu tartışarak ortadan kaldırmak yerine pratik çözüm veya destek olabilir. Teslim tarihi gerçekten kaçtıysa önce düzeltme gerekir. Kendin hakkında geniş hüküm vermemek, sorumluluğunu görmezden gelmek anlamına gelmez. Hem olayı hem yapılabilecek işi açık tut."]},{heading:"Gençlere yönelik program tek alıştırmadan fazlasıydı",paragraphs:["Brunwasser ve arkadaşları, Penn Resiliency Programı’nın 2.498 genci kapsayan 17 kontrollü araştırmasını inceledi. [O05] Hiçbir uygulama yapılmayan gruplara göre depresyon belirtilerindeki etkiler küçüktü: hemen ardından d = 0,11, altı ile sekiz ayda 0,21, on iki ayda 0,20. Başka etkin uygulamalara üstünlük ve depresyon tanılarını önleme gösterilmedi.","Program birçok düşünme ve davranış becerisini öğretiyordu. Bulgular, yetişkinin tek bir ABCDE çalışmasını doğrulamaz veya ODA’nın yanıt alıştırmasının etkisini söylemez. Yöntemi öğrenmek, planı kaydetmek ve işe yarayan bir yanıtı göndermek ayrı olaylar olarak kalsın. Gerçek adımın kanıtı, gönderdiğini bildirdiğin yanıttır. Planı güzel yazmış olman, mesajı kullandığını veya işin düzeldiğini tek başına göstermez. Bunları gözle.","Kurstaki denemeyi gündelik, güvenli bir aksilikle sınırla. Teslim tarihinin kaçırılması düzeltme gerektirebilir. Değerin hakkında bir hükme dönüşmesi gerekmez. Planın zamanına veya imkânlarına sığmıyorsa beklentiyi değiştir ya da yardım iste. Aynı düşünceyi tekrar tekrar tartışıp durmak, eksik zamanı yaratmaz. Yapılabilir bir adım ve koşullara uyan bir süre seç. Gerçekte neyi yaptığını ve neyin kaldığını ayrı ayrı kaydet."]}],sourceIds:["optimism-ellis-abc","optimism-reivich-mrt","optimism-brunwasser"]}},{schemaVersion:2,revision:2,id:"optimism-4",courseId:"optimism",locale:"tr",title:"Yanıt yok. Kaygılandığın şeyin kanıtı var mı?",goal:"Bildiğin olayla tahminini ayır. Sonra aynı aksilik hakkında ulaşabileceğin tek bir bilgiyi kontrol et.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıt gelmedi, sen şimdiden hüküm verdin mi? Planını bu yoruma göre kurmadan önce tek bir bilgiyi kontrol et.",reason:{id:"optimism-4-reason",label:"Hangi bilgi, atmak üzere olduğun bir sonraki adımı değiştirirdi?",kind:"text",maxLength:160,optional:!0,suggestions:["Tahmin etmeden önce kontrol etmek","Gerçek bir kaygıyı görünür tutmak","Eksik olan bilgiyi doğrudan sormak"]},why:{id:"optimism-4-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe dön. “Bugün yanıt gelmedi” bildiğin bir olay. “Beni yine reddettiler” ise destekleyen bilgi yoksa tahmin. Dengeli bir yanıt, gerçek kaygıyla eksik bilgiyi birlikte tutar. Belirsizlik kalabilir. Açıklama hâlâ canını sıkabilir. Rahatlatıcı olması, doğru olmasıyla aynı şey değildir. Önce gerçekten bildiğin kısmı bul.","Kaynaklarda anlatılan düşünce kaydı klinik bir araç. Tedavinin bütünü için bulunan kanıt, kısa bir formun tek başına işe yaradığını göstermez. Kısa bir kontrol yap: olay, yorum, ulaşabileceğin bilgi ve sonraki iş. Tarafsız bir soru sor veya bilinen sorunu düzelt. Tekrarlayan irdeleme sıkıntını artırırsa dur. Kaygı puanının düşmesi şart değil."],example:{title:"Ece eksik yanıtı soruyor",text:"Ece’nin düzelttiği bölüme yanıt gelmemiş. Yöneticisinin seyahatte olduğunu biliyor. Planlı görüşmede bütçe açıklamasının yönergeye uyup uymadığını soruyor. “Az kaldı, varsayımı ekle” yanıtını alıp bunu düzeltiyor. Daha geniş bir ret bekliyordu. Ama bütün kaygılarını temelsiz ilan etmek yerine gerçekten aldığı geri bildirimi kaydediyor. Sorunun ne olduğunu bu yanıttan öğrendi. Sonraki adımını ona göre seçti."}},move:{invitation:"Aynı aksilikte ulaşabileceğin tek bilgiyi kontrol et. Sonra onun gösterdiği adımı at.",instructions:["Bildiğin olayı tahmin ettiğin anlamdan ayrı tut.","Tarafsız tek soru sor veya bilgilerin gösterdiği sorunu düzelt."],prompts:[],suggestions:{action:["İşin durumu hakkında tarafsız tek soru sor","Gerçekte istenen koşulu bir kez kontrol et","Doğrulanan sorunu ele alıp düzelt"],minimum:["Bir bilgiyi kontrol eden tek cümle gönder","İlgili tek bir koşulu doğrula","Bilgilerin gösterdiği tek hatayı düzelt"],cue:["Planladığımız güvenli görüşmenin zamanı geldiğinde","İlgili bilgiye ulaşabileceğim fırsat geldiğinde","Tahminime göre harekete geçmeden önce"],place:["Güvenle geri bildirim alabildiğim iletişim kanalında","Gerçekte istenen koşul önümde açıkken"],fallback:["Kontrol için daha sonraki uygun fırsatı seç","Bunun yerine birinden pratik yardım iste","Aynı irdelemeyi tekrarlamayı bırak ve ara ver"],observation:["Kontrolden önce gerçekten ne bildiğim","Aldığım yanıtın hangi bilgiyi doğruladığı","Yeni bilgiyle planımın değişip değişmediği"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşin durumu hakkında tarafsız tek soru sor",minimum:"Bir bilgiyi kontrol eden tek cümle gönder",minutes:2,cueHint:"Planladığımız güvenli görüşmenin zamanı geldiğinde",placeHint:"Güvenle geri bildirim alabildiğim iletişim kanalında",obstacleHint:"Gerçek bilgi gereken bir belirsizliği tekrar tekrar düşünüyorum.",fallbackHint:"Kontrol için daha sonraki uygun fırsatı seç",observationHint:"Kontrolden önce gerçekten ne bildiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-4-deadline-check-decision",scenario:"Ece’nin taslağına yanıt gelmemiş. Seyahatteki yöneticisi bugünkü görüşmede konuşabilir. Göndermek için otuz dakika kalmış. Gerek düzeltme gerek yedek öneri yirmi dakika alacak.",question:"Kalan zamanı ilk hangi adımla daha iyi kullanır?",options:[{id:"optimism-4-submit-current",text:"Sessizliği seyahat açıklayabileceği ve süre daraldığı için taslağın mevcut hâlini şimdi hemen göndermek.",feedback:"Şimdi göndermek süreyi korur. Ama seyahat, taslağın yönergeye uyduğunu kanıtlamaz. Kısa görüşme gereken düzeltmeyi gösterebilir. Ardından bunu yapmak için yirmi dakika kalır. Önce ulaşılabilir bilgiyi kullan."},{id:"optimism-4-check-uncertainty",text:"Sessizliğin nedenini belirsiz bırakıp görüşmede taslağı sormak ve gerçekten gelen yanıta göre düzeltmek.",feedback:"Yönetici ulaşılabilirken ve iş yapmak için hâlâ zaman varken ilgili belirsizliği kontrol eder. Yanıt düzeltmeyi veya yedek öneriyi destekleyebilir. Denemenin ölçüsü kaygının azalması değil, bilgiyi kullanarak harekete geçmesidir."},{id:"optimism-4-backup-and-timeline",text:"Her iki seçeneği açık tutmak için yedek öneriye başlarken kararın ne zaman verileceğini mesajla sormak.",feedback:"Geri bildirim alınamıyorsa yedek plan seçenekleri koruyabilir. Burada yönetici şimdi ulaşılabilir ve iki yol da yirmi dakika alır. Kalan zamanı bilinen ihtiyaca ayırmak için önce taslağı sor."}],bestOptionId:"optimism-4-check-uncertainty"}},carry:{takeaway:"Dengeli yanıt, gerçek kaygıyı ve belirsizliği korur. Bilgiyi kontrol etmek için işe yarayan bir yol gösterir.",followUp:{questionId:"optimism-4-return",question:"Kontrol ettiğin bilgi neyi doğruladı? Sonraki planın bu bilgiye göre değişti mi?",observationPrompt:"Yeni bilgi neyi doğruladı? Hangi kısım hâlâ bilinmiyor veya yanıt bekliyor?",adjustmentPrompt:"Bu bilgiye göre sıradaki hangi adımını değiştirmelisin?"}},goDeeper:{sections:[{heading:"Tedavi kanıtı bütün programa aittir",paragraphs:["Hofmann ve arkadaşları bilişsel davranışçı terapiye ait 269 meta-analiz belirledi ve bunlardan temsili 106’sını inceledi. [O06] Bu sayılar derlemelerin sayısını gösterir. Düşünce kayıtlarının tek başına sınandığı 269 deney demek değil. Makale, farklı bileşenleri ve sorunları içeren tedavi programlarını özetler. Bu alıştırma için tek bir toplam katılımcı sayısı veya her duruma uyan etki vermez. Araştırmadaki tedavi programını buradaki kısa alıştırmayla aynı sayma.","Tedavi programları birden fazla yöntem ve desteği birleştirir. Kanıtları, bu kısa bilgi kontrolünün kendi başına etkisini göstermez. Kontrolü pratik bir belirsizliği yanıtlamak için kullan: Hangi koşul önemli? Düzeltme gerekiyor mu? Karar ne zaman gelecek? Yeni bilgi yoksa aynı irdelemeyi tekrarlamak yerine belirsizliği açık bırak. “Henüz bilmiyorum” kaydı, olmayan bir yanıtı varsaymaktan daha doğrudur. Sonraki uygun kontrol fırsatını ayrıca seçebilirsin.","Beck Institute’un formu klinik bir yöntemi anlatır. [O13] Yöntemin tek başına etkisini bağımsız olarak göstermez. Bu ders, tek bir tahmine bakabilmek için kısaltılmış bir uyarlama kullanır. Sonra öğrendiklerini zaten üzerinde çalıştığın aynı işte kullanırsın. Formu doldurmayı işin yerine koyma. Soruyu sormak veya desteklenen düzeltmeyi yapmak, ayrı olarak kaydedeceğin gerçek adım olabilir."]},{heading:"Puanlar hedef değil, gözlem sağlar",paragraphs:["Kaynakta anlatılan düşünce kaydı, düşünce ve duygu puanlarını, kanıtı, dengeli yanıtı ve sonraki puanları içerir. [O13] Sayılar değişen şeyi anlatabilir. Puanı düşürmek zorunlu olursa senden istenen cevabı yazman için baskı doğar. Dengeli yanıt, kaygı hâlâ haklı görünse de eldeki bilgiye uymalı. Puanın aynı kalması, adımı yapmadığın anlamına gelmez.","ODA belirli bir düşünce hatasının adını koymanı veya belli bir duygu puanına ulaşmanı istemez. “Bildiğim” ve “tahmin ettiğim” ayrımı, kontrol edeceğin tek bilgiyi seçmene yetebilir. Bilgilerin desteklediği kaygı bir düzeltme, sınır veya pratik yardım gerektirebilir. Yeni bir rahatlatıcı açıklama her zaman en yararlı adım değildir. Önündeki sorunun gerçek kısmını koru ve yapabileceğin işin ne olduğunu açıkça söyle.","NHS rehberi bilişsel davranışçı terapiyi düzenli profesyonel tedavi olarak anlatır. [O16] Kendi başına irdelemek sıkıntını artırıyorsa veya yeni bilgi olmadan tekrarlanıyorsa durabilirsin. Gerektiğinde uygun yardım iste. Gerçek yanıtı ve yaptığın işi kurs kaydına ekle. Kaygının azalmasını, asıl işin yapıldığının kanıtı olarak kullanma. Yanıt gelmemesi veya sorunun sürmesi de yazılabilir. Bunlar sonraki kararın için bilgi sağlar."]}],sourceIds:["optimism-hofmann","optimism-beck-thought-record","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-5",courseId:"optimism",locale:"tr",title:"Yine mi iptal? İhtiyacını açıkça söyle",goal:"Aynı aksilikte riski düşük bir varsayımına bak. Sonra güvenli bir istek veya sınırı açıkça ilet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Görüşme iptal olunca üstüne mi alınıyorsun? Nedenini merak ederken hâlâ gereken isteği de açıkça söyle.",reason:{id:"optimism-5-reason",label:"Varsayımını gözden geçirdikten sonra hangi istek veya sınır hâlâ gerekli?",kind:"text",maxLength:160,optional:!0,suggestions:["Tahmin etmek yerine doğrudan sormak","Gerekli olan bir sınırı korumak","Merak ederken bütün suçu üstlenmemek"]},why:{id:"optimism-5-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Karşı tarafın amacı bilinmese de senin ihtiyacın gerçek olabilir. Aynı aksiliğe dön. Güvenli bir değerlendirme görüşmesi iptal edildiğinde “Umursamıyorlar” demek olanı aşabilir. “Katılabileceğim bir görüşme saatine ihtiyacım var” ise doğru kalabilir. Birini haklı veya haksız ilan etmeden de bu ihtiyacını açıkça söyleyebilirsin.","Rehber eşliğindeki uzun sorgulama programı, katılımcıların rastgele gruplara ayrıldığı bir araştırmada sınandı. Bu, kendi kendine soracağın dört sorunun tedavi olduğunu göstermez. Sorgulama işe yarıyorsa kullan, sonra isteğini veya sınırını ilet. Düşünceyi tersine çevirip kendini suçlaman veya örnek uydurman gerekmiyor. Tehlike ve kötü davranışı dışarıda tut. Merak etmek, o kişiyle görüşmeni veya kendini korumaktan vazgeçmeni gerektirmez."],example:{title:"Ece görüşme isteğini açıklaştırıyor",text:"Ece’nin iş arkadaşı rapor görüşmesini iki kez iptal ediyor. Saat 8.00’de “Beni umursamıyor” varsayımına bakıyor. Tersinin kesin doğru olduğunu da söylemiyor. “Perşembeye kadar bakabilir misin? Olmazsa başka birinden değerlendirme alacağım” diye gönderiyor. Arkadaşı söz veremiyor. Ece isteğini kaydedip güvenle görüşebileceği başka birini buluyor. Hayal kırıklığı sürüyor. Yine de ihtiyacını açıkça iletmiş oluyor."}},move:{invitation:"Güvenli bir durumda, nedenini henüz bilmesen de ihtiyacını veya sınırını açıkça söyle.",instructions:["Gerçek ihtiyaçlarını ve sana gereken sınırları görünür tut.","Tek bir açık istek gönder. Tamamlamak için karşı tarafın kabul etmesi gerekmiyor."],prompts:[],suggestions:{action:["Bana uyan bir geri bildirim saati iste","Değerlendirme için pratik tek sınır belirt","Güvenli başka bir yoldan geri bildirim al"],minimum:["Görüşme saati isteyen tek açık mesaj gönder","Tek bir sınırı saygıyla açıkça söyle","Alternatif tek bir değerlendirme iste"],cue:["Güvenli bir değerlendirme görüşmemiz iptal edildiğinde","Sıradaki uygun görüşmemizin zamanı geldiğinde","Üzerinde anlaştığımız sınıra gelindiğinde"],place:["Güvenle geri bildirim alabildiğim mesaj grubunda","Her zamanki iletişim yöntemimi kullanırken"],fallback:["Rapora güvenle bakacak başka birini seç","Bunun yerine pratik yardım almayı seç","Sıkıntımı artıran sorgulamaya ara ver"],observation:["Gerçekte hangi isteği ilettiğim","Gelen yanıt veya anlaşmaya varılamaması","Sınırın hâlâ duruma uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bana uyan bir geri bildirim saati iste",minimum:"Görüşme saati isteyen tek açık mesaj gönder",minutes:2,cueHint:"Güvenli bir değerlendirme görüşmemiz iptal edildiğinde",placeHint:"Güvenle geri bildirim alabildiğim mesaj grubunda",obstacleHint:"Düşünüp duruyorum, ama hâlâ iletmem gereken doğrudan isteği erteliyorum.",fallbackHint:"Rapora güvenle bakacak başka birini seç",observationHint:"Gerçekte hangi isteği ilettiğim"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri dışarıda tut. Kendini suçlamaya zorlama. Sıkıntı veren sorgulamaya ara ver.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-5-decision",scenario:"Ece güvenle konuşabildiği iş arkadaşıyla rapora bakacaktı. Arkadaşı iki kez iptal etti. Nedenleri belirsiz. Ece’nin bu hafta geri bildirim alması gerekiyor.",question:"Hangi yanıt hem merakı hem işe yarayan bir sınırı korur?",options:[{id:"optimism-5-finish-alone",text:"Gerginliği azaltmak için değerlendirmeyi tek başına bitirip sonraki projede arkadaşından yardım istemeyi yeniden düşünmek.",feedback:"Değerlendirme isteğe bağlıysa veya gereken beceri varsa tek başına çalışmak uygun olabilir. Burada Ece’nin bu hafta hâlâ geri bildirime ihtiyacı var. Uyan bir saat iste veya rapora güvenle bakacak başka birini bul."},{id:"optimism-5-flexible-slot",text:"Arkadaşı uygun olduğunda seçebilsin diye yeni, esnek bir saat önerip görüşme düzenlemesini ucu açık bırakmak.",feedback:"Esneklik iş birliğini koruyabilir. Ama iki iptal ve bu haftaki son tarih, ucu açık düzenlemeyi riskli yapıyor. İhtiyacın karşılanabilsin diye uygun saatin yanında bir alternatif de belirle."},{id:"optimism-5-request-with-limit",text:"Arkadaşının amacını kesinleştirmeden uygun bir değerlendirme saati istemek, olamazsa kullanacağı alternatifi de açıkça söylemek.",feedback:"Belirsizliği ve pratik ihtiyacı birlikte korur. Arkadaşı reddederse Ece alternatif yolu kullanabilir. Onun kendi adımı isteği göndermektir. Diğer kişinin iş birliği yapması, Ece’nin kontrolünde olmayan bir sonuç olarak kalır."}],bestOptionId:"optimism-5-request-with-limit"}},carry:{takeaway:"Nedeninden emin olmadığın yorumu sorgula. Gerçek isteğini veya gerekli sınırını korumaya devam et.",followUp:{questionId:"optimism-5-return",question:"İsteğin veya sınırın neyi değiştirdi? Aynı sınır hâlâ seçtiğin amaca hizmet ediyor mu?",observationPrompt:"İstekten veya sınırdan sonra ne değişti? Yanıt gelmediyse bunu da ayrı yaz.",adjustmentPrompt:"Bu sınır hâlâ sana uyuyor mu, yoksa şimdi değişmesi mi gerekiyor?"}},goDeeper:{sections:[{heading:"Araştırmada uzun bir program ve rehber desteği vardı",paragraphs:["Landau ve arkadaşları, BRCA varyantları olan 100 kadınla kaydı yapılmış randomize bir araştırmada sorgulamaya dayalı stres azaltmayı sınadı. [O11] Program on iki hafta sürdü. Her hafta üç saatlik grup ve bir saatlik rehber desteğiyle çalışma vardı. Karşılaştırma olağan sağlık bakımıydı. Bazı iyi oluş sonuçlarında fayda bildirildi. Ama karşılaştırma grubuna aynı miktarda ilgi ve zaman sağlanmamıştı. Bu fark, bulgunun yorumunu sınırlar.","Bulgular, kendi kendine soracağın dört kısa sorunun tedavi olduğunu, yöntemin bilişsel davranışçı terapiye eşdeğerliğini veya sonuçların istismar ve travmaya uyduğunu göstermez. Katılımcılar, süre ve uygulama biçimi, buradaki gündelik rapor görüşmesi örneğinden oldukça farklı. İsteğini pratik bir ihtiyaca dayandır. Klinik iyileşme vaadine dayanması gerekmez. Kullanılabilir bir değerlendirme saati istemek, bu araştırmanın programıyla aynı işlem değildir.","ODA’nın istek alıştırması bir eğitim uyarlaması. Düşünmek yardım ediyorsa gereken gerçek görüşmeye geri dön. Kullanabileceğin bir saat iste ve elinde alternatif bulundur. Etkisini henüz bilmeden de isteğini göndermiş olabilirsin. Başkasının iş birliği yapması iyimserliğini ölçen bir sınav değildir. Yanıt gelmediyse veya karşı taraf uygun değilse bu bilgiyi koru. Sonraki adımı ihtiyacına ve koşullarına göre seç."]},{heading:"Sorgulama isteğe bağlı, kendini suçlamak zorunlu değil",paragraphs:["Byron Katie’nin uygulama yönergeleri dört soru kullanır: Düşünce doğru mu? Kesin emin olabilir misin? Ona inanmak yanıtını nasıl etkiliyor? Ona daha az tutunduğunda ne değişiyor? [O15] Ardından düşünceyi başka yönden ele almayı ve gerçek örnekler bulmayı anlatır. Bu bir yöntem kaynağıdır. Tek başına bu soruların etkili tedavi olduğunun kanıtı değildir. Buradaki kısa çalışmayla araştırmadaki uzun uygulama birbirinden ayrı kalır.","Düşünceyi tersine çevirmek her zaman isteğe bağlı. Belli sayıda örnek bulman gerekmiyor. Örnek uydurma. Sana verilen zararın sorumluluğunu üstüne atan bir yorum, bulman gereken sonuç değildir. Karşı tarafın nedenleri belirsizken de açık bir istek veya sınır gerekli olabilir. Merakla yaklaşmak ihtiyacından vazgeçmek demek değil. Bilmediğin şeyi açık tutarken bildiğin ihtiyacı doğrudan söyleyebilirsin.","Sorgulamayı gündelik, güvenli sıkıntılarla sınırla. NHS rehberi tedavi için profesyonel yardım yollarını anlatır. [O16] ODA bunların yerini almaz. Tehlike, istismar, kendine zarar verme kaygısı ve ciddi belirtilerde korunma ile uygun destek gerekir. Alıştırmayı durdurup pratik bir yanıt seçebilirsin. Bunun için önce bir düşünceyi çözmen veya başka biriyle yeniden görüşmen gerekmez. Güvenli sınır, dinlenme ve yardım isteme seçeneklerin açık kalsın."]}],sourceIds:["optimism-landau-inquiry","optimism-katie-instructions","optimism-nhs-cbt"]}},{schemaVersion:2,revision:2,id:"optimism-6",courseId:"optimism",locale:"tr",title:"Zor hafta geçti. İşe yarayan neyi sürdüreceksin?",goal:"Aynı aksilikte yaptığın denemelere bak. Yardım eden koşulu ve yapabileceğin sonraki fırsatı seçerek devam et.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hafta hâlâ zordu. İşe yarayan hangi adımı veya desteği bir kez daha denemeye değer buluyorsun?",reason:{id:"optimism-6-reason",label:"Seçtiğin amaca ne yardım etti? Hangi sorun hâlâ bir adım gerektiriyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Yardım eden tek koşulu tekrarlamak","Çözülemeyen sorunu görünür tutmak","Yapabileceğim bir sonraki denemeyi seçmek"]},why:{id:"optimism-6-direction",label:"Bu adım bu hafta senin için neden önemli?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı aksiliğe ve attığın adıma bak. Ne yaptın, ne yardım etti, hangi sorun çözülemedi? Zor bir haftada işe yarayan destek de olabilir. İyi hissetmeni şart koşmadan, gördüğün bu bilgilere göre sonraki fırsatı seç. Zorluğu silmen veya bütün haftayı başarılı ilan etmen gerekmiyor. Yardım eden kısmı açıkça belirle.","İlk “üç iyi şey” araştırması, bir hafta boyunca her gece üç olayı ve nedenlerini yazdırdı. Tekrar araştırmasında olumlu plaseboyla da mutluluk artışı görüldü. Bu, yalnızca adı geçen alıştırmanın işe yaradığını söylemeyi zorlaştırır. Burada gerçek bir yararlı olay fark edebilirsin; hiçbiri de olmayabilir. Yeni bir gece rutini eklemeden aynı denemeyi sürdür."],example:{title:"Ece yardım eden koşulu sürdürüyor",text:"Cuma günü Ece’nin raporu hâlâ onay bekliyor. Kaydında işe yarayan bir neden var: rapora bakacak başka birini bulunca belirli bir düzeltme öğrendi. Masasında bu düzeltmeyi yapıp sonraki uygun görüşmeyi ayarlıyor. Haftayı başarılı saymadan yardımı not ediyor. Sonraki denemesinde aynı raporu, daha küçük işi ve koşullarına uyan bir dönüş tarihini koruyor. Onay gelip gelmeyeceği hâlâ belirsiz."}},move:{invitation:"Aynı denemeye dönüp bak. Yardım eden tek koşulu tekrarla ve yapabileceğin sonraki adımı seç.",instructions:["Gerçek yardımı not ederken çözülememiş sorunları da görünür tut.","Sonraki tek denemeyi, destek isteğini veya ara vermeyi seç."],prompts:[],suggestions:{action:["Geri bildirimin gösterdiği düzeltmeyi gerçekten yap","İşe yarayan toparlanma adımımı tekrar dene","İşime yarayan desteği yeniden iste"],minimum:["Taslağın bilinen tek eksiğini gider","Seçtiğim toparlanma adımının bir kısmını tamamla","Belirli bir destek isteyen tek mesaj gönder"],cue:["Taslak üzerinde çalışabileceğim ilk uygun fırsatta","İşime yarayan geri bildirim geldiğinde","Destek istemek için seçtiğim an geldiğinde"],place:["Üzerinde çalıştığım mevcut taslağın başında","Güvenle yardım isteyebildiğim iletişim yolunda"],fallback:["Gerçekte yapacağım toparlanma adımını küçült","Ara ver, yeniden bakmak için tarih seç","Yapabileceğim başka bir destek yolunu kullan"],observation:["Adımı atmama neyin yardım ettiği","Hangi sorunun hâlâ çözülemediği","Sonraki adımın haftama uyup uymadığı"],minutes:[2,1,5],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Geri bildirimin gösterdiği düzeltmeyi gerçekten yap",minimum:"Taslağın bilinen tek eksiğini gider",minutes:2,cueHint:"Taslak üzerinde çalışabileceğim ilk uygun fırsatta",placeHint:"Üzerinde çalıştığım mevcut taslağın başında",obstacleHint:"İşe yarayan adımı iyileştirmek yerine yeni rutinler ekliyorum.",fallbackHint:"Gerçekte yapacağım toparlanma adımını küçült",observationHint:"Adımı atmama neyin yardım ettiği"},stopRule:"Tehlike, istismar, kendine zarar verme ve ciddi belirtileri bu çalışmanın dışında tut. Aynı şeyi tekrar tekrar irdelemeyi bırak; destek iste.",accessibleAlternative:"Her zamanki iletişim yöntemini, pratik yardımı veya güvenli bir sınırı seçebilirsin."},result:{question:"Seçtiğin en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Ardından ne oldu, ne olmadı?"},judgment:{primary:{id:"optimism-6-correction-scope-decision",scenario:"Raporu inceleyen kişi Ece’nin raporunda eksik bir varsayım bulmuş. Kalanı yönergeye uyuyor. Beş dakikalık düzeltmeyi yapmak için teslim öncesi yirmi dakika var. Onay hâlâ belirsiz.",question:"Yardım eden geri bildirimi hangi sonraki adımla daha iyi kullanır?",options:[{id:"optimism-6-repeat-helpful-cause",text:"Doğrulanan eksiği düzeltip süre dolmadan göndermek ve onay alacağını varsaymadan gerçekte çıkan sonucu kaydetmek.",feedback:"Bu seçim, onayı belirsiz tutarken belirli geri bildirimi kullanır. Düzeltme kalan zamana sığar ve aynı raporu ilerletir. Değişen kısmı ve gelen yanıtı kaydet. Yanıt yoksa onu da açıkça yaz."},{id:"optimism-6-check-scope",text:"Daha geniş bir sorunu kaçırmamak için düzeltmeden önce raporu inceleyen kişiden kapsamı bir kez daha kontrol etmesini istemek.",feedback:"Kapsam belirsizse bir kontrol daha işe yarayabilir. Burada raporu inceleyen kişi kapsamı zaten doğruladı. Beklemek, yeni bir belirsizliği çözmeden teslim süresini tüketebilir. Önce belirtilen tek düzeltmeyi yap."},{id:"optimism-6-request-extension",text:"Düzeltmeyi yapmadan önce raporun tamamına yeniden bakabilmek için teslim tarihinin kısa bir süre uzatılmasını istemek.",feedback:"Zaman veya güç yetmiyorsa ek süre işi koruyabilir. Burada belirtilen düzeltme süreye sığıyor. Yeni bir düzenleme istemek, bilinen engeli çözmeden başka iş ekler. Daha geniş kontrol bekleyebilir."}],bestOptionId:"optimism-6-repeat-helpful-cause"}},carry:{takeaway:"Yardım eden koşulu ve yapılabilir adımı sürdür. Haftanın zor olduğu gerçeğini değiştirmeye çalışma.",followUp:{questionId:"optimism-6-return",question:"Yardım eden koşulu tekrarlamak sonraki adımına destek oldu mu? Hangi kısım düzeltme, yardım veya bırakma gerektiriyor?",observationPrompt:"Hangi koşul yardım etti? Hangi sorun hâlâ çözülmedi veya yanıt bekliyor?",adjustmentPrompt:"Koşulu tekrarlamak, işi değiştirmek, yardım almak veya bırakmak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Araştırmada üç olay ve nedenleri yazılıyordu",paragraphs:["Seligman ve arkadaşlarının ilk çevrim içi araştırmasında katılımcılar, bir hafta boyunca her gece iyi giden üç şeyi ve her birinin nedenini yazdı. [O07] Başlangıçta 577 kişi vardı. Analizde takibi tamamlayan 411 kişi kullanıldı. Çoğu beyaz, eğitimli, çevrim içi gönüllülerdi. Alıştırmalarla erken bir anıyı yazma karşılaştırmasına katılımcılar rastgele atandı. Sonradan çalışmayı sürdürüp sürdürmemeleri ise rastgele belirlenmedi.","İlk deney mutluluk ve depresyon anketlerinde değişim bildirdi. Bu, devam etmenin sonraki faydayı koruduğunu, on dakikanın zorunlu süre olduğunu veya şükranın depresyonu tedavi ettiğini göstermez. Daha sonraki tekrar araştırmasında olumlu plaseboyla da mutluluk iyileşmesi görüldü. Depresyon için bu alıştırmaya özgü bir fayda gösterilmedi. [O08] Ortalamanın değişmesiyle değişimi yalnızca belirli bir alıştırmaya bağlamak, aynı iddia değildir. Araştırmanın sınırlarını birlikte tut.","Uygunsa ilk araştırmadaki bir haftalık çalışmayı ayrıca seçebilirsin. Tek bir iyi veya nötr olay fark etmek ya da zor bir gecede ara vermek, kişiye alan tanıyan bir uyarlamadır. Araştırmada sınanan yöntemin aynısı değildir. Bu kursun sonu ise mevcut toparlanma adımını sürdürmeye yarar. Yeni gece görevleri biriktirmek zorunda değilsin. Ne yaptığınla ne hissettiğini birbirine karıştırmadan sonraki uygun fırsatı belirle."]},{heading:"Gelecek hafta işe yarasa da sonuç belirsiz kalabilir",paragraphs:["Psikolojik dayanıklılık eğitiminin açıklaması, plan yapmadan önce en kötü, en iyi ve en olası ihtimalleri düşünmeyi anlatır. [O14] Bu kısa çalışmanın tek başına etkisini göstermez. Mevcut denemende belirli bir belirsizlik için plan gerekiyorsa kullan. Başka bir zorunlu rutine dönüşmesi gerekmez. Sadece gözlediğin ihtiyaca cevap veren kısmı seç.","Duruma gerçekçi bakmak, hem işe yarayan koşulu hem kalan sorunu görmeyi gerektirir. Rapor onaylanmamışken de raporu inceleyen kişinin yardımı işe yaramış olabilir. Belirli bir soru sormak, zaman ayırmak veya destek almak işe yaramış olabilir. Sonraki fırsata uyuyorsa tekrarla. Şükran hissetmek şart değil. Yardımın önemini yazmak, haftanın zor taraflarını silmez. Yardım eden şeyin kendisini ve henüz çözülmeyen ihtiyacı ayrı ayrı söyleyebilirsin.","Gelecek haftadan önce aynı denemenin kayıtlarını gözden geçir. İşe yarayan küçük adımı, tanıyabileceğin başlama anını ve kullanabileceğin alternatifi koru. Duruma göre destek, dinlenme, sınır veya bırakma seç. Gelecek planları, düşünme çalışması ve sorulara verdiğin yanıtlar, gerçek denemelerden ayrı kalsın. Neyin belirsiz kaldığını ve yanıt gelmediğini de kaydet. Yeni fırsatı, hayal edilen sonuç yerine gerçekte gördüğün koşullara göre belirle."]}],sourceIds:["optimism-three-good-things","optimism-mongrain","optimism-reivich-mrt"]}}],m=[{id:"optimism-1",practice:["Gündelik bir aksilik seç. Elindeki bir imkânı dene, sonra gerçekte ne olduğunu kaydet.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:1,photo:{id:"1527580094867-0e719f119120",alt:"Güneşin doğmasını beklerken sabahın erken saatinde gri kayalardan geçen yürüyüşçü"}},{id:"optimism-2",practice:["Aynı aksiliği kullan. Doğru bir neden belirle, sonra onun gerektirdiği düzeltmeyi yap.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:2,photo:{id:"1509029032154-54ba8b3216d4",alt:"Gözlüklü bir adam düşünceli biçimde pencereden dışarı bakıyor"}},{id:"optimism-3",practice:["Aynı aksilikte inancına kısaca bak. Ardından duruma uygun, adil tek bir yanıtı ver.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:0,photo:{id:"1643148636630-0b0fb138fc74",alt:"Kalemle deftere yazı yazan bir kişi"}},{id:"optimism-4",practice:["Aynı aksilikte ulaşabileceğin tek bilgiyi kontrol et. Sonra onun gösterdiği adımı at.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:1,photo:{id:"1681396059172-7532b1ef8b47",alt:"Yumuşak sabah ışığında masada açık duran günlük"}},{id:"optimism-5",practice:["Güvenli bir durumda, nedenini henüz bilmesen de ihtiyacını veya sınırını açıkça söyle.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:2,photo:{id:"1503541517233-120571491cf3",alt:"Ağaçların arasında park bankında gözleri kapalı oturan bir adam"}},{id:"optimism-6",practice:["Aynı denemeye dönüp bak. Yardım eden tek koşulu tekrarla ve yapabileceğin sonraki adımı seç.","Seçtiğin başlama anında kaydettiğin en küçük adımı dene veya ara verdiğini kaydet.","Gerçekte olanı buraya kaydet. Seçtiğin tarihte yeniden bakıp sonraki denemeni belirle."],correct:0,photo:{id:"1750885847789-f5748b585e3a",alt:"Balkondan şehre bakan bir kadın"}}],s={id:"optimism",title:"Tek aksilik her şeyi mi kapattı?",subtitle:"6 ders. Aynı aksiliği incele, uygun bir adım at, gerçekte olandan öğren.",description:"Gündelik bir aksiliği yerli yerine koy. Acı veren gerçekleri koru, belirsiz yorumlara bak ve istediğin hayata katkı sağlayan pratik bir yanıt seç.",outcome:"Bir aksilik, denenebilir toparlanma adımı ve gerçekte olana göre sonraki plan.",scope:"Aksilikten sonra vazgeçmeye, kendini suçlamaya veya en kötüsünü beklemeye yatkın yetişkinler için. Martin Seligman’ın öğrenilmiş iyimserliğinden, bilişsel davranışçı terapiden (BDT) ve Byron Katie’nin The Work yönteminden yararlanır. Kişisel gelişim desteğidir. Depresyon, kaygı veya başka bir durumun tedavisi değildir; terapi veya ilacın yerini almaz. Umutsuzluk sürüyorsa veya günlük hayatı sürdürmek zorlaşıyorsa bir doktora ya da ruh sağlığı uzmanına başvur. Daha erken yardım da isteyebilirsin. İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan.",photo:{id:"1465188162913-8fb5709d6d57",alt:"Akşamın altın rengi ışığında tepede yürüyen bir kadın"},lang:"tr",lessons:d.map((e,t)=>{const n=m[t],a=e.judgment.primary,r=a.options.find(i=>i.id===a.bestOptionId),l=a.options.filter(i=>i.id!==a.bestOptionId).map(i=>i.text);return l.splice(n.correct,0,r.text),{...n,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,reflection:e.direction.reason.label,question:`${a.scenario} ${a.question}`,options:l,feedback:r.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds}})};export{s as COURSE,d as LESSONS_V2,k as SOURCES};
